#!/usr/bin/env python3
"""Build supabase/tests/fixtures/30_hosted_structure.sql from a hosted catalog snapshot.

The snapshot is the read-only, structure-only catalog pull of the hosted project
(client-portal-pm docs/schema-snapshot/<date>/out). This script turns it back into SQL that
recreates the same schemas, types, tables, constraints, indexes, functions, views, materialized
views, triggers, RLS flags, policies and grants on a local cluster, so the 1.6 migrations and
guard tests run against the hosted structure. No rows: the snapshot has none.

    python3 -I supabase/tests/fixtures/build_hosted_fixture.py <snapshot>/out \
        > supabase/tests/fixtures/30_hosted_structure.sql

Not reproduced (and why): extensions other than pgcrypto / uuid-ossp (pg_cron, vault and
pg_stat_statements are platform services; cron jobs are listed as comments only); Supabase
platform roles are created as plain NOLOGIN roles with their BYPASSRLS flag; object owners are
all postgres on hosted and postgres here.
"""
import json
import re
import sys
from pathlib import Path

APP_SCHEMAS = ["canvas_private", "command", "ledlenser", "ledlenser_private", "private", "public", "sandbox"]
BUILTIN_ROLES = {"postgres", "anon", "authenticated", "service_role", "authenticator"}


def q(ident: str) -> str:
    return '"' + ident.replace('"', '""') + '"'


def lit(s: str) -> str:
    return "'" + s.replace("'", "''") + "'"


def load(out: Path, name: str):
    return json.loads((out / f"{name}.json").read_text())


def parse_sql_blocks(text: str):
    """Split 06-views.sql / 07-functions.sql into (header, body) blocks."""
    blocks, header, body = [], None, []
    for line in text.splitlines():
        if line.startswith("-- ") and (" kind=" in line):
            if header:
                blocks.append((header, "\n".join(body).strip()))
            header, body = line, []
        else:
            body.append(line)
    if header:
        blocks.append((header, "\n".join(body).strip()))
    return blocks


def main(out: Path):
    w = []
    p = w.append
    p("-- GENERATED by supabase/tests/fixtures/build_hosted_fixture.py from the hosted catalog")
    p("-- snapshot (structure only, no rows). Do not edit by hand; regenerate. Test-only, not a migration.")
    p("set check_function_bodies = off;")
    p("set client_min_messages = warning;")
    p("")

    # Roles -------------------------------------------------------------------------------------
    roles = load(out, "11-roles")
    p("-- Roles (platform roles as plain roles; only BYPASSRLS and LOGIN matter to these tests)")
    for r in roles:
        if r["name"] in BUILTIN_ROLES:
            continue
        attrs = ["LOGIN" if r["login"] else "NOLOGIN", "BYPASSRLS" if r["bypassrls"] else "NOBYPASSRLS",
                 "INHERIT" if r["inherit"] else "NOINHERIT"]
        p(f"do $$ begin if not exists (select 1 from pg_roles where rolname = {lit(r['name'])}) then "
          f"create role {q(r['name'])} {' '.join(attrs)}; end if; end $$;")
    for r in roles:
        for m in r["member_of"] or []:
            if m.startswith("pg_") or r["name"] == "postgres":
                continue
            p(f"grant {q(m)} to {q(r['name'])};")
    p("")

    # Schemas, extensions -----------------------------------------------------------------------
    for s in load(out, "01-schemas"):
        p(f"create schema if not exists {q(s['schema'])};")
    p("create schema if not exists extensions;")
    p('create extension if not exists pgcrypto with schema extensions;')
    p('create extension if not exists "uuid-ossp" with schema extensions;')
    p("")

    # Types -------------------------------------------------------------------------------------
    for t in load(out, "03-types"):
        name = f"{q(t['schema'])}.{q(t['name'])}"
        if t["kind"] == "enum":
            p(f"create type {name} as enum ({', '.join(lit(x) for x in t['enum_labels'])});")
        elif t["kind"] == "domain":
            line = f"create domain {name} as {t['domain_base']}"
            if t.get("domain_default"):
                line += f" default {t['domain_default']}"
            if t.get("domain_notnull"):
                line += " not null"
            for c in t.get("domain_constraints") or []:
                line += f" {c if isinstance(c, str) else c.get('def', '')}"
            p(line + ";")
        elif t["kind"] == "composite":
            attrs = ", ".join(f"{q(a['name'])} {a['type']}" for a in t["composite_attrs"])
            p(f"create type {name} as ({attrs});")
    p("")

    # Tables (no defaults or constraints yet: those can call functions) -------------------------
    tables = load(out, "04-tables")
    seqs = set(re.findall(r"nextval\('([^']+)'", json.dumps(tables)))
    # Sequences are not captured as objects; recreate the ones named in defaults or grants.
    seqs |= {f"{r['schema']}.{r['relation']}" for r in load(out, "10-grants")["relation_grants"] if r.get("kind") == "S"}
    for s in sorted(seqs):
        p(f"create sequence if not exists {s.replace(chr(92), '')};")
    for t in tables:
        name = f"{q(t['schema'])}.{q(t['name'])}"
        cols = []
        for c in sorted(t["columns"], key=lambda c: c["n"]):
            col = f"{q(c['name'])} {c['type']}"
            if c.get("generated"):
                # Snapshot: generated = 's' (stored), expression in default.
                col += f" generated always as ({c['default']}) stored"
            if c.get("identity"):
                col += " generated always as identity" if c["identity"] in ("a", "always") else " generated by default as identity"
            if c["not_null"] and not c.get("identity"):
                col += " not null"
            cols.append(col)
        part = " partition by ..." if t.get("kind") == "p" else ""
        assert not part, f"partitioned table {name} not supported"
        p(f"create table {name} ({', '.join(cols)});")
    p("")

    # Functions ---------------------------------------------------------------------------------
    p("-- Functions (bodies not checked at create, as on a restore)")
    fn_text = (out / "07-functions.sql").read_text()
    for header, body in parse_sql_blocks(fn_text):
        p(header)
        p(body.rstrip().rstrip(";") + ";")
        p("")

    # Defaults and constraints ------------------------------------------------------------------
    for t in tables:
        name = f"{q(t['schema'])}.{q(t['name'])}"
        for c in t["columns"]:
            if c.get("default") and not c.get("generated") and not c.get("identity"):
                p(f"alter table {name} alter column {q(c['name'])} set default {c['default']};")
    for t in tables:
        name = f"{q(t['schema'])}.{q(t['name'])}"
        for k in t["constraints"] or []:
            if k["type"] in ("p", "u", "c", "x"):
                p(f"alter table {name} add constraint {q(k['name'])} {k['def']};")
    constraint_names = {(t["schema"], k["name"]) for t in tables for k in (t["constraints"] or [])}
    table_names = {(t["schema"], t["name"]) for t in tables}
    deferred_indexes = []
    for i in load(out, "05-indexes"):
        if (i["schema"], i["index"]) in constraint_names:
            continue
        if (i["schema"], i["table"]) not in table_names:
            deferred_indexes.append(i)  # on a materialized view: after the views
            continue
        p(i["def"].replace("CREATE INDEX ", "CREATE INDEX IF NOT EXISTS ", 1)
              .replace("CREATE UNIQUE INDEX ", "CREATE UNIQUE INDEX IF NOT EXISTS ", 1) + ";")
    for t in tables:
        name = f"{q(t['schema'])}.{q(t['name'])}"
        for k in t["constraints"] or []:
            if k["type"] == "f":
                p(f"alter table {name} add constraint {q(k['name'])} {k['def']} not valid;")
    p("")

    # Views and materialized views, created in dependency order by retrying --------------------
    p("-- Views and materialized views (retried until every one is created)")
    views = []
    for header, body in parse_sql_blocks((out / "06-views.sql").read_text()):
        m = re.match(r"-- (\S+)\s+kind=(view|materialized view)\s+owner=\S+\s+reloptions=\{(.*)\}", header)
        assert m, header
        views.append({"name": m.group(1), "kind": m.group(2), "reloptions": m.group(3),
                      "sql": body.rstrip().rstrip(";")})
    p("create temporary table _fixture_views (name text, sql text, done boolean default false);")
    for v in views:
        stmt = v["sql"]
        if v["reloptions"]:
            stmt += f";\nalter {'materialized view' if v['kind'] != 'view' else 'view'} {v['name']} set ({v['reloptions']})"
        p(f"insert into _fixture_views (name, sql) values ({lit(v['name'])}, {lit(stmt)});")
    p("""do $$
declare v record; progress boolean := true; last_err text;
begin
  while progress loop
    progress := false;
    for v in select * from _fixture_views where not done loop
      begin
        execute v.sql;
        update _fixture_views set done = true where name = v.name;
        progress := true;
      exception when undefined_table or undefined_column or undefined_function then
        last_err := v.name || ': ' || sqlerrm;
      end;
    end loop;
  end loop;
  if exists (select 1 from _fixture_views where not done) then
    raise exception 'fixture views not created: % (last error %)',
      (select string_agg(name, ', ') from _fixture_views where not done), last_err;
  end if;
end $$;
drop table _fixture_views;""")
    for i in deferred_indexes:
        p(i["def"].replace("CREATE INDEX ", "CREATE INDEX IF NOT EXISTS ", 1)
              .replace("CREATE UNIQUE INDEX ", "CREATE UNIQUE INDEX IF NOT EXISTS ", 1) + ";")
    p("")

    # Triggers, RLS, policies -------------------------------------------------------------------
    for tr in load(out, "08-triggers"):
        p(tr["def"] + ";")
        if tr.get("enabled") == "D":
            p(f"alter table {q(tr['schema'])}.{q(tr['table'])} disable trigger {q(tr['trigger'])};")
    for t in tables:
        if t["rls_enabled"]:
            p(f"alter table {q(t['schema'])}.{q(t['name'])} enable row level security;")
        if t.get("rls_forced"):
            p(f"alter table {q(t['schema'])}.{q(t['name'])} force row level security;")
    for pol in load(out, "09-policies"):
        roles_ = ", ".join("public" if r == "public" else q(r) for r in pol["roles"])
        line = (f"create policy {q(pol['policyname'])} on {q(pol['schemaname'])}.{q(pol['tablename'])} "
                f"as {pol['permissive'].lower()} for {pol['cmd'].lower()} to {roles_}")
        if pol.get("qual"):
            line += f" using ({pol['qual']})"
        if pol.get("with_check"):
            line += f" with check ({pol['with_check']})"
        p(line + ";")
    p("")

    # Grants ------------------------------------------------------------------------------------
    g = load(out, "10-grants")
    p("-- Grants exactly as hosted: clear what local defaults gave, then apply the snapshot")
    for s in APP_SCHEMAS:
        p(f"revoke all on all tables in schema {q(s)} from public, anon, authenticated, service_role;")
        p(f"revoke all on all functions in schema {q(s)} from public, anon, authenticated, service_role;")
        p(f"revoke all on schema {q(s)} from public, anon, authenticated, service_role;")
    for r in g["schema_grants"]:
        grantee = "public" if r["grantee"] in ("PUBLIC", "public", "-") else q(r["grantee"])
        p(f"grant {r['privilege']} on schema {q(r['schema'])} to {grantee};")
    for r in g["relation_grants"]:
        # MAINTAIN exists from Postgres 17 (hosted); local tests may run on 16.
        privs = ",".join(x for x in r["privileges"].replace("*", "").split(",") if x != "MAINTAIN")
        if not privs:
            continue
        grantee = "public" if r["grantee"] in ("PUBLIC", "public", "-") else q(r["grantee"])
        what = "sequence" if r.get("kind") == "S" else "table"
        p(f"grant {privs} on {what} {q(r['schema'])}.{q(r['relation'])} to {grantee};")
    for r in g["column_grants"]:
        p(f"grant {r['privilege']} ({q(r['column'])}) on {q(r['schema'])}.{q(r['relation'])} to {q(r['grantee'])};")
    for r in g["routine_grants"]:
        grantee = "public" if r["grantee"] in ("PUBLIC", "public", "-") else q(r["grantee"])
        # GRANT accepts the signature with argument names; drop DEFAULT clauses.
        sig = re.sub(r"\s+DEFAULT\s+[^,)]*(\([^)]*\))?[^,)]*", "", r["routine"], flags=re.I)
        p(f"grant {r['privileges'].replace('*', '')} on function {q(r['schema'])}.{sig} to {grantee};")
    p("")
    p("-- Default privileges (application schemas only)")
    for d in g["default_privileges"]:
        if d["schema"] not in APP_SCHEMAS or not d.get("for_role") or d["for_role"] != "postgres":
            continue
        objtype = {"r": "tables", "f": "functions", "S": "sequences", "T": "types"}.get(d["object_type"])
        if not objtype:
            continue
        for entry in d["acl"].strip("{}").split(","):
            grantee, rest = entry.split("=", 1)
            privs = rest.split("/")[0]
            if not grantee or grantee == "postgres":
                continue
            names = {"r": "select", "a": "insert", "w": "update", "d": "delete", "D": "truncate",
                     "x": "references", "t": "trigger", "X": "execute", "U": "usage"}  # m (maintain): Postgres 17 only
            plist = ", ".join(sorted({names[c] for c in privs if c in names}))
            if plist:
                p(f"alter default privileges for role postgres in schema {q(d['schema'])} grant {plist} on {objtype} to {q(grantee)};")
    p("")
    p("-- pg_cron jobs on hosted (not created locally):")
    for j in load(out, "12-cron-jobs"):
        p(f"--   {j['jobname']} ({'active' if j['active'] else 'inactive'}) {j['schedule']}: {j['command']}")
    p("reset check_function_bodies;")
    p("reset client_min_messages;")
    sys.stdout.write("\n".join(w) + "\n")


if __name__ == "__main__":
    main(Path(sys.argv[1]))
